     9	export type { Item, Customer };
    10	export type { Incident, Damage } from "./claims.js";
    11	
    12	/** A policy MHPCO has written: what it covers and what it was quoted for. */
    13	export interface Policy {
    14	  readonly premium: number;
    15	  readonly insuranceSum: number;
    16	  readonly items: readonly Item[];
    17	  /** What the office may still pay out on this policy. */
    18	  readonly remainingCap: number;
    19	}
    20	
    21	/**
    22	 * The settlement of one claim: what MHPCO pays, and the policy as it stands
    23	 * afterwards — a claim consumes part of the cap, so later claims against the
    24	 * same policy are settled against what is left.
    25	 */
    26	export interface Settlement {
    27	  readonly payout: number;
    28	  readonly remainingCap: number;
    29	  readonly policy: Policy;
    30	}
    31	
    32	/**
    33	 * Writes a policy for the items the customer wishes to insure: the premium they
    34	 * owe, and the insurance sum the office's payouts are measured against.
    35	 */
    36	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
    37	  const insuranceSum = policyInsuranceSum(items);
    38	  return {
    39	    premium: quote(customer, items),
    40	    insuranceSum,
    41	    items,
    42	    remainingCap: payoutCap(insuranceSum),
    43	  };
    44	}
    45	
    46	/** The insured item a damage report entry refers to. */
    47	function damagedItem(policy: Policy, damage: Damage): Item {
    48	  const item = policy.items.find((insured) => insured.type === damage.itemType);
    49	  if (item === undefined) {
    50	    throw new Error(`the policy does not cover an item of type "${damage.itemType}"`);
    51	  }
    52	  return item;
    53	}
    54	
    55	/** Settles a damage report against a policy MHPCO has written. */
    56	export function claim(policy: Policy, incident: Incident): Settlement {
    57	  const reimbursement = incident.damages.reduce(
    58	    (total, damage) => total + damageReimbursement(damage, damagedItem(policy, damage)),
    59	    0,
    60	  );
    61	  const { payout, remainingCap } = capPayout(reimbursement, policy.remainingCap);
    62	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
    63	}
    64	
    65	/** MHPCO adds a flat processing fee to every premium, at the very end. */
    66	const PROCESSING_FEE_G = 5;
    67	
    68	/**
    69	 * Assembles the bill in the order the office bills it: the price-list base
    70	 * premium of the policy, the risk surcharges its individual items carry, the
    71	 * modifiers rated on the policy as a whole, and finally the processing fee.
    72	 *
    73	 * Each of those amounts is ruled on elsewhere; this function only knows the
    74	 * order they are applied in and that the total is rounded once, at the end.
    75	 */
    76	export function quote(customer: Customer, items: readonly Item[]): number {
    77	  const policyBase = policyBasePremium(items);
    78	  const premium =
    79	    policyBase +
    80	    itemRiskSurcharges(items) +
    81	    policyModifiers(customer, policyBase) +
    82	    PROCESSING_FEE_G;
    83	  return roundPremiumInMHPCOFavour(premium);
    84	}
