     1	/**
     2	 * MHPCO's building-block rule for components.
     3	 *
     4	 * This module owns one underwriting policy: when a number of components
     5	 * qualifies as a building block, and what the office charges for it instead of
     6	 * the per-component rate. Two rulings live here, and they are the office's to
     7	 * revise: what counts as "alike" (MHPCO reads it as "of the same type", so two
     8	 * runes and a moonstone are not three alike components, and 3 runes with 3
     9	 * moonstones earn two separate blocks), and how large a block is and what it
    10	 * costs.
    11	 *
    12	 * It is kept apart from the price list because the two change for different
    13	 * reasons: the price of a rune is a catalogue revision, while the size, rate or
    14	 * the very meaning of a building block is a bundling decision the office makes
    15	 * on its own.
    16	 */
    17	
    18	import { type Item } from "./item.js";
    19	
    20	/** MHPCO offers a building block of exactly this many alike components. */
    21	const BLOCK_SIZE = 3;
    22	const BLOCK_BASE_PREMIUM_G = 60;
    23	
    24	/**
    25	 * MHPCO reads "alike" as "of the same type". Grouping components by type is
    26	 * therefore the office's ruling on what counts as alike, and the sizes of these
    27	 * groups are what the block rule is applied to.
    28	 */
    29	function alikeComponentGroupSizes(components: readonly Item[]): number[] {
    30	  const sizeByType = new Map<string, number>();
    31	  for (const component of components) {
    32	    sizeByType.set(component.type, (sizeByType.get(component.type) ?? 0) + 1);
    33	  }
    34	  return [...sizeByType.values()];
    35	}
    36	
    37	/**
    38	 * The base premium for a group of alike components: the block rate when the
    39	 * group is exactly a building block, the per-component rate otherwise.
    40	 */
    41	function alikeComponentsBasePremium(count: number, perComponentRateG: number): number {
    42	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * perComponentRateG;
    43	}
    44	
    45	/**
    46	 * The base premium MHPCO charges for a policy's components, at the given
    47	 * per-component rate. Components are priced per group of alike components, not
    48	 * per item: the office gathers the alike ones together first so that a building
    49	 * block can be recognised, then prices each group on its own.
    50	 */
    51	export function componentsBasePremium(
    52	  components: readonly Item[],
    53	  perComponentRateG: number,
    54	): number {
    55	  return alikeComponentGroupSizes(components).reduce(
    56	    (total, groupSize) => total + alikeComponentsBasePremium(groupSize, perComponentRateG),
    57	    0,
    58	  );
    59	}
