     1	/**
     2	 * MHPCO's rounding rule: every final amount is rounded in the office's own
     3	 * favour.
     4	 *
     5	 * This module owns that single ruling. Which way "the office's favour" points
     6	 * depends on which way the money flows — a premium the customer owes is rounded
     7	 * up, an amount the office pays out is rounded down — so the direction is the
     8	 * office's decision, not arithmetic the caller should make for itself.
     9	 *
    10	 * Only final amounts are rounded; intermediate amounts stay fractions.
    11	 */
    12	
    13	/** A premium the customer owes MHPCO is rounded up. */
    14	export function roundPremiumInMHPCOFavour(premium: number): number {
    15	  return Math.ceil(premium);
    16	}

